 if(p.height==='fill'){if(!parent)s.height='100%';else if(axis==='column')s.flex='1 1 0';else s.height='100%';}else if(typeof p.height==='number'){s.height=p.height+'px';if(axis==='column')s.flex='0 0 '+p.height+'px';}
