function renderCanvas(){const l=history.current;$('canvas').replaceChildren(nodeView(findNode(l,'workspace'),l));fit();}
function fit(){const w={desktop:1180,narrow:860,mobile:390}[ui.device];$('viewport').dataset.device=ui.device;$('viewport').style.setProperty('--viewport-width',w+'px');zoomRatio=ui.zoom==='fit'?Math.max(.2,Math.min(1,($('stage-scroll').clientWidth-48)/w)):Number(ui.zoom)/100;$('viewport').style.zoom=zoomRatio;$('zoom-readout').textContent=Math.round(zoomRatio*100)+'%';}
